#pragma once

#include <QString>
#include <QVector>
#include <optional>

#include "domain/note.h"

/// Data-access contract for notes. Implementations are synchronous and are
/// expected to be used from a single thread (the storage worker).
class INoteRepository {
public:
    virtual ~INoteRepository() = default;

    virtual QVector<Note> getAll() = 0;
    virtual std::optional<Note> getById(int id) = 0;
    virtual bool add(const Note &note) = 0;
    virtual bool update(const Note &note) = 0;
    virtual bool remove(int id) = 0;

    /// Id generated by the last successful add().
    virtual int lastInsertId() const = 0;
    /// Empty when the last operation succeeded.
    virtual QString lastError() const = 0;
};
